/* AP United States Government and Politics, Unit 1: Foundations of American Democracy. Original teaching and practice
   aligned to the topics of the College Board's AP U.S. Government and Politics Course and Exam Description: 1.1 Ideals of
   Democracy, 1.2 Types of Democracy, 1.3 Government Power and Individual Rights, 1.4 Challenges of the Articles of
   Confederation, 1.5 Ratification of the U.S. Constitution, 1.6 Principles of American Government, 1.7 Relationship Between
   the States and the Federal Government, 1.8 Constitutional Interpretation of the Commerce Clause, 1.9 Federalism in Action.
   Required foundational documents used here: the Declaration of Independence, the Articles of Confederation, Federalist
   No. 10, Brutus No. 1 and the Constitution; required cases used here: McCulloch v. Maryland and United States v. Lopez.
   Only short passages of public-domain founding-era text are quoted; Brutus No. 1 is paraphrased. Dates and facts are
   standard textbook history, hedged where scholars differ. Scenarios marked fictional are teaching constructions. The
   unit is non-partisan: it explains how the institutions work and what the sources argued, not which side is right.
   Pending PixelLab art is listed in ART_REQUESTS.md; the pictures here are code-drawn meanwhile. */
const choose=(right,wrong,k)=>{const o=[...wrong];o.splice(k%3,0,right);return {text:o.map((x,i)=>`${'ABC'[i]}: ${x}`).join(', '),letter:'ABC'[o.indexOf(right)]};};
const board=(title,lines)=>({t:'board',title,lines});
const table=(title,head,col,rows)=>({t:'setups',title,head,cols:[col],rows});
const flow=(title,labels,details)=>{const pts={},polys=[],segs=[],notes=[];labels.forEach((label,i)=>{const x=i*36;for(const [j,xy] of [[0,[x,15]],[1,[x+28,15]],[2,[x+28,27]],[3,[x,27]]])pts['ABCD'[j]+i]=xy;polys.push({v:`A${i}B${i}C${i}D${i}`,label,col:i});notes.push({at:[x+14,7],text:details[i]});if(i<labels.length-1){pts['P'+i]=[x+29,21];pts['Q'+i]=[x+35,21];segs.push({v:`P${i}Q${i}`,arrows:1,col:i});}});return {t:'figure',title,view:[-3,103,0,34],pts,polys,segs,notes,dots:'',hide:Object.keys(pts).join('')};};
/* a scaled timeline: the x axis is calendar years and labels alternate above and below the line */
const years=(title,span,events)=>{const pts={A:[span[0]+4,0],B:[span[1]-4,0]},notes=[];events.forEach(([y,text],i)=>{pts['E'+i]=[y,0];notes.push({at:[y,i%2?-4.5:4.5],text});});return {t:'figure',title,view:[span[0],span[1],-9,9],pts,hide:Object.keys(pts).join(''),dots:events.map((e,i)=>'E'+i).join(''),segs:[{v:'AB',arrows:1}],notes};};
/* labelled boxes in a row or grid: schematic only */
const regions=(title,boxes)=>{const pts={},polys=[],notes=[];boxes.forEach(([label,x0,y0,x1,y1,detail],i)=>{[[x0,y0],[x1,y0],[x1,y1],[x0,y1]].forEach((xy,j)=>{pts['ABCD'[j]+i]=xy;});polys.push({v:`A${i}B${i}C${i}D${i}`,label,col:i});notes.push({at:[(x0+x1)/2,y0+2.4],text:detail});});return {t:'figure',title,view:[0,100,0,34],pts,polys,notes,dots:'',hide:Object.keys(pts).join('')};};
const ideas=years('Ideas to institutions: 1689 to 1787 (years to scale)',[1670,1800],[[1689,'1689: Locke'],[1748,'1748: Montesquieu'],[1776,'1776: Declaration'],[1787,'1787: Constitution']]);
const stages=years('From the Articles to the Bill of Rights: 1781 to 1791 (years to scale)',[1779,1793],[[1781,'1781: Articles'],[1787,'1787: Convention'],[1791,'1791: Bill of Rights']]);
const cases=years('Commerce Clause cases (years to scale)',[1800,2020],[[1824,'1824: Gibbons'],[1942,'1942: Wickard'],[1964,'1964: Heart of Atlanta'],[1995,'1995: Lopez']]);
const models=regions('Three models of democracy: schematic',[['Participatory',1,8,32,26,'broad citizen role'],['Pluralist',35,8,66,26,'groups compete'],['Elite',69,8,99,26,'few hold power']]);
const branches={t:'figure',title:'Separation of powers with checks: a simplified sketch',view:[0,100,0,34],pts:{A0:[3,18],B0:[33,18],C0:[33,31],D0:[3,31],A1:[67,18],B1:[97,18],C1:[97,31],D1:[67,31],A2:[35,2],B2:[65,2],C2:[65,11],D2:[35,11],P0:[66,27],Q0:[34,27],P1:[34,22],Q1:[66,22]},polys:[{v:'A0B0C0D0',label:'Legislative',col:0},{v:'A1B1C1D1',label:'Executive',col:1},{v:'A2B2C2D2',label:'Judicial review',col:2}],segs:[{v:'P0Q0',arrows:1,col:1},{v:'P1Q1',arrows:1,col:0}],notes:[{at:[18,20.4],text:'makes laws'},{at:[82,20.4],text:'enforces laws'},{at:[50,29.5],text:'veto'},{at:[50,19.5],text:'override, confirm, impeach'}],dots:'',hide:'A0B0C0D0A1B1C1D1A2B2C2D2P0Q0P1Q1'};
